package models

// MPlusReference is reference/mplus-dungeons.json: this season's dungeon facts for the M+ page, generated by
// cmd/mplusref from Mythic Dungeon Tools, Keystone.guru, Raider.IO and Wowhead, never typed by hand.
type MPlusReference struct {
	Season   string               `json:"season"`
	Sources  map[string]string    `json:"sources"`  // where each part came from: commit, URLs
	Dungeons map[int]DungeonFacts `json:"dungeons"` // by map ID (the combat log's challenge mode ID)
}

// DungeonFacts is one dungeon's forces table, spell lists (spell IDs) and map floors.
type DungeonFacts struct {
	Name       string         `json:"name"`
	InstanceID int            `json:"instanceID"` // the game's instance (zone) ID, from Keystone.guru
	Guide      string         `json:"guide"`
	Floors     []DungeonFloor `json:"floors"` // the map's floors from Keystone.guru, for the replay
	Forces     Forces         `json:"forces"`
	Bosses     []int          `json:"bosses"`     // NPC IDs Mythic Dungeon Tools marks as bosses
	Minibosses []int          `json:"minibosses"` // NPC IDs of trash worth at least twice the median forces count
	MustStop   []int          `json:"mustStop"`   // the guide's important interrupts that Mythic Dungeon Tools marks interruptible
	Avoidable  []int          `json:"avoidable"`  // the guide's Dodge, Avoid, Run Away and Hide tips
	Soak       []int          `json:"soak"`       // the guide's Soak tips: shown, never counted as avoidable
	Dispel     []int          `json:"dispel"`     // the guide's important dispels and Dispel tips (debuffs on players)
	Purge      []int          `json:"purge"`      // the guide's important purges (buffs on enemies)
	Review     []int          `json:"review"`     // interrupts the guide names that Mythic Dungeon Tools doesn't mark interruptible
	MDTIndex   int            `json:"mdtIndex"`   // Mythic Dungeon Tools' dungeonIndex, which its routes name
	Enemies    []RouteEnemy   `json:"enemies"`    // every enemy a route can pull, by (Index, Clone)
}

// RouteEnemy is one enemy a Mythic Dungeon Tools route can pull: its enemy and clone index there, its NPC, the forces
// one kill gives, its pack (clicking a pack takes all of it) and where it stands in log yards on the floor Map.
type RouteEnemy struct {
	Index int     `json:"index"`
	Clone int     `json:"clone"`
	NPC   int     `json:"npc"`
	Count int     `json:"count"`
	Boss  bool    `json:"boss,omitempty"`
	Pack  int     `json:"pack"` // Keystone.guru's pack, else Mythic Dungeon Tools' group, else 0
	X     float64 `json:"x"`
	Y     float64 `json:"y"`
	Map   int     `json:"map"` // the floor's UIMapID
}

// DungeonFloor is one floor of a dungeon's map from Keystone.guru: the combat log's map ID for it, its in-game
// bounds (Keystone.guru's x is the log's -y and its y the log's x), and its tile folder on Keystone.guru's assets
// ("bfa/templeofsethraliss/1").
type DungeonFloor struct {
	RaidMap
	Tiles string `json:"tiles"`
}

// DungeonMap is what the replay draws a dungeon on: its floors with map tiles (none for a dungeon Keystone.guru
// doesn't map), and where parties have walked in its saved runs, and its enemies.
type DungeonMap struct {
	Floors  []DungeonFloor `json:"floors"`
	Walked  []TrackPoint   `json:"walked"`
	Enemies []RouteEnemy   `json:"enemies"` // what a route can pull, for the route map
}

// Forces is a dungeon's enemy forces: the total a key needs and each NPC's count (0 for the mobs Mythic Dungeon Tools
// lists as worth nothing, so a mob missing from it stands out).
type Forces struct {
	Total int         `json:"total"`
	NPCs  map[int]int `json:"npcs"`
}

// MDTDungeon is one dungeon in Mythic Dungeon Tools' data: its index there, forces, mobs by NPC ID, each mob spell's
// flags and every placed enemy.
type MDTDungeon struct {
	Name   string
	Index  int
	MapID  int
	Total  int
	Mobs   map[int]MDTMob
	Spells map[int]MDTSpell
	Clones []MDTClone
}

// MDTClone is one placed enemy in Mythic Dungeon Tools' data: its enemy and clone index, its NPC, its place on the
// sublevel's 840 by 555 map (y negative, down) and its group.
type MDTClone struct {
	Index, Clone, NPC int
	X, Y              float64
	Sublevel, Group   int
}

// MDTPreset is a Mythic Dungeon Tools route: its name, uid, dungeon index and pulls. Raw is the whole preset as CBOR,
// so the fields the app doesn't read (drawings, week, difficulty) survive a round trip.
type MDTPreset struct {
	Name       string
	UID        string
	DungeonIdx int
	Pulls      []MDTPull
	Raw        []byte
}

// MDTPull is one pull of a route: its color ("ff3eff") and its enemies, enemy index to clone indexes.
type MDTPull struct {
	Color   string
	Enemies map[int][]int
}

// KeystoneGuruEnemy is an enemy on Keystone.guru's newest mapping of a dungeon: the NPC, the NPC Mythic Dungeon
// Tools lists it as when that differs (else 0), its Mythic Dungeon Tools clone index, its pack (0 for none), its
// place on the floor's 384 by 256 map (lat negative, down) and that floor's UIMapID.
type KeystoneGuruEnemy struct {
	NPC, MDTNPC, MDTID, Pack int
	Lat, Lng                 float64
	Map                      int
}

// MDTMob is a mob in Mythic Dungeon Tools' data.
type MDTMob struct {
	Name  string
	Count int
	Boss  bool
}

// MDTSpell is a mob spell's flags in Mythic Dungeon Tools' data.
type MDTSpell struct {
	Interruptible bool
	Magic         bool
}

// DungeonGuide is what a Wowhead dungeon overview tags: its important interrupts, dispels and purges table (spell ID
// to the mob casting it) and its boss tips (spell ID to the tip's tag, "Dodge").
type DungeonGuide struct {
	URL        string
	Interrupts map[int]string
	Dispels    map[int]string
	Purges     map[int]string
	Tips       map[int]string
}
